<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Balls in a Rotating Hexagon</title>
<style>
  body,html{margin:0;padding:0;overflow:hidden;background:#111}
  canvas{display:block;background:#222}
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = innerWidth;
  const H = canvas.height = innerHeight;

  // ---- Parameters ----
  const BALL_COUNT = 10;
  const BALL_RADIUS = 12;
  const GRAVITY = 0.3;
  const FRICTION = 0.99; // air friction
  const WALL_FRICTION = 0.8; // energy loss on wall hit
  const HEX_RADIUS = Math.min(W, H) * 0.4;
  const HEX_ROT_SPEED = 0.001; // radians per frame

  // ---- Helper ----
  function rand(min, max){return Math.random()*(max-min)+min;}
  function vecLen(v){return Math.hypot(v.x,v.y);}
  function dot(a,b){return a.x*b.x + a.y*b.y;}
  function reflect(v,n){
    // reflect vector v across normal n (n normalized)
    const d = dot(v,n);
    return {x: v.x - 2*d*n.x, y: v.y - 2*d*n.y};
  }

  // ---- Ball class ----
  class Ball{
    constructor(x,y,vx,vy,color){
      this.x=x;this.y=y;this.vx=vx;this.vy=vy;this.c=color;
    }
    update(){
      // gravity
      this.vy += GRAVITY;
      // air friction
      this.vx *= FRICTION;
      this.vy *= FRICTION;
      // move
      this.x += this.vx;
      this.y += this.vy;
    }
    draw(){
      ctx.beginPath();
      ctx.arc(this.x,this.y,BALL_RADIUS,0,Math.PI*2);
      ctx.fillStyle=this.c;
      ctx.fill();
    }
  }

  // ---- Create balls ----
  const balls=[];
  const colors = ['#e74c3c','#f1c40f','#2ecc71','#3498db','#9b59b6','#e67e22','#1abc9c','#ff6b6b','#ff9f43','#48dbfb'];
  for(let i=0;i<BALL_COUNT;i++){
    const angle = rand(0,2*Math.PI);
    const r = HEX_RADIUS*0.5;
    const x = W/2 + Math.cos(angle)*r;
    const y = H/2 + Math.sin(angle)*r;
    const vx = rand(-2,2);
    const vy = rand(-2,2);
    balls.push(new Ball(x,y,vx,vy,colors[i%colors.length]));
  }

  // ---- Hexagon walls ----
  function getHexVertices(angle){
    const verts=[];
    for(let i=0;i<6;i++){
      const a = angle + i*Math.PI/3;
      verts.push({x: W/2 + Math.cos(a)*HEX_RADIUS, y: H/2 + Math.sin(a)*HEX_RADIUS});
    }
    return verts;
  }

  // ---- Collision with walls ----
  function wallCollisions(ball, verts){
    for(let i=0;i<6;i++){
      const a = verts[i];
      const b = verts[(i+1)%6];
      // line vector
      const lx = b.x - a.x;
      const ly = b.y - a.y;
      const length = Math.hypot(lx,ly);
      const nx = -ly/length; // outward normal (approx)
      const ny = lx/length;
      // distance from ball centre to line
      const px = ball.x - a.x;
      const py = ball.y - a.y;
      const dist = px*nx + py*ny;
      if(dist < BALL_RADIUS){
        // check if moving towards the wall
        const velDot = ball.vx*nx + ball.vy*ny;
        if(velDot < 0){
          // reflect velocity
          const refl = reflect({x:ball.vx,y:ball.vy},{x:nx,y:ny});
          ball.vx = refl.x * WALL_FRICTION;
          ball.vy = refl.y * WALL_FRICTION;
          // push out of wall
          const overlap = BALL_RADIUS - dist;
          ball.x += nx*overlap;
          ball.y += ny*overlap;
        }
      }
    }
  }

  // ---- Ball-ball collisions ----
  function ballCollisions(){
    for(let i=0;i<balls.length;i++){
      for(let j=i+1;j<balls.length;j++){
        const b1=balls[i], b2=balls[j];
        const dx=b2.x-b1.x, dy=b2.y-b1.y;
        const dist=Math.hypot(dx,dy);
        if(dist < BALL_RADIUS*2){
          // normal
          const nx=dx/dist, ny=dy/dist;
          // relative velocity
          const rvx=b2.vx-b1.vx, rvy=b2.vy-b1.vy;
          const relVel=rvx*nx + rvy*ny;
          if(relVel>0) continue; // moving apart
          // impulse (elastic, mass =1)
          const impulse = -2*relVel/(1+1);
          const ix=impulse*nx, iy=impulse*ny;
          b1.vx -= ix;
          b1.vy -= iy;
          b2.vx += ix;
          b2.vy += iy;
          // separate overlapping balls
          const overlap = BALL_RADIUS*2 - dist;
          b1.x -= nx*overlap/2;
          b1.y -= ny*overlap/2;
          b2.x += nx*overlap/2;
          b2.y += ny*overlap/2;
        }
      }
    }
  }

  // ---- Animation loop ----
  let hexAngle = 0;
  function animate(){
    ctx.clearRect(0,0,W,H);

    // draw rotating hexagon
    const verts = getHexVertices(hexAngle);
    ctx.beginPath();
    ctx.moveTo(verts[0].x, verts[0].y);
    for(let i=1;i<6;i++) ctx.lineTo(verts[i].x, verts[i].y);
    ctx.closePath();
    ctx.strokeStyle = '#fff3';
    ctx.lineWidth = 4;
    ctx.stroke();

    // update balls
    for(const b of balls){
      b.update();
      wallCollisions(b, verts);
    }
    ballCollisions();

    // draw balls
    for(const b of balls) b.draw();

    // rotate hexagon slowly
    hexAngle += HEX_ROT_SPEED;
    requestAnimationFrame(animate);
  }
  animate();
})();
</script>
</body>
</html>
```

The script creates ten colored balls that fall under gravity, lose speed via friction, bounce elastically off each other and the six rotating walls of a slowly spinning hexagon drawn on a canvas.
